CREATE TABLE g_meta (singleton INTEGER PRIMARY KEY CHECK(singleton=1), schema_version INTEGER NOT NULL, revision INTEGER NOT NULL);
CREATE TABLE g_scopes (id INTEGER PRIMARY KEY, project_key TEXT NOT NULL, root TEXT NOT NULL, worktree TEXT NOT NULL, UNIQUE(project_key, root, worktree));
CREATE TABLE g_sources (id INTEGER PRIMARY KEY, scope INTEGER NOT NULL REFERENCES g_scopes(id), kind TEXT NOT NULL, locator TEXT NOT NULL, sha256 TEXT NOT NULL, version TEXT NOT NULL, state TEXT NOT NULL, observed_at INTEGER NOT NULL, UNIQUE(scope, kind, locator, sha256, version));
CREATE TABLE g_nodes (id INTEGER PRIMARY KEY, scope INTEGER NOT NULL REFERENCES g_scopes(id), key TEXT NOT NULL, kind TEXT NOT NULL, entry_id INTEGER UNIQUE REFERENCES entries(id) ON DELETE SET NULL, label TEXT NOT NULL DEFAULT '', summary TEXT NOT NULL DEFAULT '', attrs TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(attrs)), source INTEGER REFERENCES g_sources(id), state TEXT NOT NULL, revision INTEGER NOT NULL, UNIQUE(scope, key));
CREATE TABLE g_edges (src INTEGER NOT NULL REFERENCES g_nodes(id) ON DELETE CASCADE, dst INTEGER NOT NULL REFERENCES g_nodes(id) ON DELETE CASCADE, kind TEXT NOT NULL, source INTEGER NOT NULL REFERENCES g_sources(id), locator TEXT NOT NULL DEFAULT '', weight INTEGER NOT NULL CHECK(weight BETWEEN 0 AND 1000), state TEXT NOT NULL, attrs TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(attrs)), PRIMARY KEY(src, dst, kind, source, locator));
CREATE INDEX g_edges_in ON g_edges(dst, kind, state); CREATE INDEX g_edges_source ON g_edges(source); CREATE INDEX g_nodes_kind ON g_nodes(scope, kind, state);
CREATE TABLE g_files (scope INTEGER NOT NULL REFERENCES g_scopes(id), path TEXT NOT NULL, node INTEGER NOT NULL REFERENCES g_nodes(id), source INTEGER NOT NULL REFERENCES g_sources(id), language TEXT NOT NULL, bytes INTEGER NOT NULL, PRIMARY KEY(scope, path));
CREATE TABLE g_refs (id INTEGER PRIMARY KEY, source INTEGER NOT NULL REFERENCES g_sources(id), owner INTEGER NOT NULL REFERENCES g_nodes(id), name TEXT NOT NULL, kind TEXT NOT NULL, locator TEXT NOT NULL, resolution TEXT NOT NULL, target INTEGER REFERENCES g_nodes(id) ON DELETE SET NULL, candidates TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(candidates)), UNIQUE(source, owner, kind, locator));
CREATE INDEX g_refs_name ON g_refs(name, resolution);
CREATE TABLE g_aliases (old_id INTEGER PRIMARY KEY REFERENCES g_nodes(id), new_id INTEGER NOT NULL REFERENCES g_nodes(id), CHECK(old_id<>new_id));
CREATE TABLE g_dirty_entries (entry_id INTEGER PRIMARY KEY, operation TEXT NOT NULL);
CREATE VIRTUAL TABLE g_fts USING fts5(label, summary, content='g_nodes', content_rowid='id', tokenize='trigram');
CREATE TABLE g_changes(id INTEGER PRIMARY KEY, scope INTEGER NOT NULL, at REAL NOT NULL, actor TEXT NOT NULL, op TEXT NOT NULL, target TEXT NOT NULL, reason TEXT NOT NULL, evidence TEXT NOT NULL CHECK(json_valid(evidence)), before TEXT NOT NULL CHECK(json_valid(before)), after TEXT NOT NULL CHECK(json_valid(after)));
CREATE TRIGGER g_nodes_ai AFTER INSERT ON g_nodes BEGIN INSERT INTO g_fts(rowid,label,summary) VALUES(new.id,new.label,new.summary); END;
CREATE TRIGGER g_nodes_ad AFTER DELETE ON g_nodes BEGIN INSERT INTO g_fts(g_fts,rowid,label,summary) VALUES('delete',old.id,old.label,old.summary); END;
CREATE TRIGGER g_nodes_au AFTER UPDATE OF label,summary ON g_nodes BEGIN INSERT INTO g_fts(g_fts,rowid,label,summary) VALUES('delete',old.id,old.label,old.summary); INSERT INTO g_fts(rowid,label,summary) VALUES(new.id,new.label,new.summary); END;
CREATE TRIGGER g_entries_ai AFTER INSERT ON entries BEGIN INSERT INTO g_dirty_entries VALUES(new.id,'insert') ON CONFLICT(entry_id) DO UPDATE SET operation='insert'; END;
CREATE TRIGGER g_entries_au AFTER UPDATE ON entries BEGIN INSERT INTO g_dirty_entries VALUES(new.id,'update') ON CONFLICT(entry_id) DO UPDATE SET operation='update'; END;
CREATE TRIGGER g_entries_ad AFTER DELETE ON entries BEGIN UPDATE g_nodes SET state='tombstone',entry_id=NULL,label='',summary='' WHERE entry_id=old.id; INSERT INTO g_dirty_entries VALUES(old.id,'delete') ON CONFLICT(entry_id) DO UPDATE SET operation='delete'; END;
CREATE TRIGGER g_entries_bd BEFORE DELETE ON entries BEGIN UPDATE g_nodes SET state='tombstone',entry_id=NULL,label='',summary='' WHERE entry_id=old.id; END;
